import {getLanguage} from './i18n.js';
import {roseraieReleases,roseraieReleaseUrl} from './roseraie-releases.js';

const t=(zh,en)=>getLanguage()==='en'?en:zh;
const repo='https://github.com/ChefDavid0815/roseraie-agent';
const release=roseraieReleaseUrl('0.2.0');
const asset='./assets/projects/roseraie/';
const home=asset+'home-0.2.0.png';
const botanical=asset+'violet-botanical.webp';
const mark=asset+'mark-0.2.0.svg';
const petals=(count=16)=>`<div class="rose-petals" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="--drift:${(i-8)*13}px;--left:${(i*31+13)%96}%;--delay:-${(i*1.19).toFixed(2)}s;--duration:${11+i%5*2}s"></i>`).join('')}</div>`;
const actions=()=>`<div class="rose-actions"><a class="rose-action-main" href="${release}" target="_blank" rel="noopener noreferrer">${t('下载 Windows 0.2','Download Windows 0.2')} <span>↓</span></a><a href="${repo}" target="_blank" rel="noopener noreferrer">GitHub <span>↗</span></a><a href="./post.html?article=roseraie">${t('读工坊的第一篇手记','Read the first atelier note')} <span>↗</span></a></div>`;

const scenes={
  salon:{zh:'灵感沙龙',en:'THE SALON',caption:['0.2.0 的真实 Windows 界面。','The actual 0.2.0 Windows interface.'],image:home,size:[2304,1517],alt:['Roseraie 0.2.0 紫罗兰色桌面工坊首页','Roseraie 0.2.0 violet desktop atelier']},
  models:{zh:'模型花园',en:'MODEL GARDEN',caption:['任务模型与推理强度可直接在沙龙选择。','Choose the task model and effort directly in the salon.'],image:asset+'models-0.2.0.png',size:[1536,960],alt:['Roseraie 0.2.0 真实模型选择界面','Actual Roseraie 0.2.0 model selection screen']},
  compact:{zh:'窄窗工坊',en:'COMPACT VIEW',caption:['较窄的窗口仍能打开工作区与手账。','The workspace and journal remain available in a narrow window.'],image:asset+'mobile-0.2.0.png',size:[390,844],alt:['Roseraie 0.2.0 窄窗口实际界面','Actual Roseraie 0.2.0 compact window']}
};
const scene=(id)=>{const item=scenes[id]||scenes.salon;return `<figure class="rose-v2-scene ${id==='compact'?'rose-v2-scene--compact':''}"><img src="${item.image}" width="${item.size[0]}" height="${item.size[1]}" alt="${t(...item.alt)}" loading="lazy"><figcaption>${t('真实桌面界面','ACTUAL DESKTOP CAPTURE')} / WINDOWS x64</figcaption></figure>`};

export function roseraieGallery(id='salon'){
  const active=scenes[id]||scenes.salon;
  return `<section class="rose-gallery rose-v2-gallery" data-rose-gallery="${id}"><div class="rose-gallery-heading"><span>THE ATELIER / ACTUAL WINDOWS CAPTURES</span><p>${t('在真实界面里，看看这间工坊。','See the atelier through its real interface.')}</p></div><div class="rose-gallery-layout"><div class="rose-gallery-rail" role="group" aria-label="${t('切换展柜画面','Choose an exhibit plate')}">${Object.entries(scenes).map(([key,item],i)=>`<button type="button" data-rose-view="${key}" aria-pressed="${key===id}"><small>0${i+1}</small><span>${t(item.zh,item.en)}</span><b>↗</b></button>`).join('')}<p>${t('画面来自本机实际运行的 0.2.0 版本。','Captures come from the actual 0.2.0 application.')}</p></div><div class="rose-gallery-stage" aria-live="polite">${scene(id)}</div></div><div class="rose-gallery-caption"><span>FIG. 0${Object.keys(scenes).indexOf(id)+1}</span><span>${t(...active.caption)}</span><span>ROSERAIE / 2026</span></div></section>`;
}
export function changeRoseraieView(button){
  const host=button.closest('[data-rose-gallery]'),id=button.dataset.roseView;
  if(!host||!scenes[id]||host.dataset.roseGallery===id)return;
  host.dataset.roseGallery=id;
  host.querySelectorAll('[data-rose-view]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));
  host.querySelector('.rose-gallery-stage').innerHTML=scene(id);
  host.querySelector('.rose-gallery-caption').innerHTML=`<span>FIG. 0${Object.keys(scenes).indexOf(id)+1}</span><span>${t(...scenes[id].caption)}</span><span>ROSERAIE / 2026</span>`;
  document.dispatchEvent(new Event('roseraie:render'));
}

export function roseraieHistory(id='roseraie-history'){
  return `<details class="rose-v2-history" id="${id}"><summary><span class="rose-v2-history-seal" aria-hidden="true">R<span>✧</span></span><span class="rose-v2-history-intro"><small>THE EDITION JOURNAL</small><strong>${t('版本手记','Release journal')}</strong><em>${t('从第一朵蔷薇，到紫罗兰工坊。','From the first rose to the violet atelier.')}</em></span><span class="rose-v2-history-route" aria-hidden="true">0.1 <i>→</i> 0.2</span><span class="rose-v2-history-plus" aria-hidden="true">＋</span></summary><div class="rose-v2-history-pages">${roseraieReleases.map((item,index)=>{const content=item[getLanguage()==='en'?'en':'zh'];return `<article class="rose-v2-history-page" data-edition="${item.version}"><div class="rose-v2-history-date"><span>${index===0?'LATEST EDITION':'FIRST EDITION'}</span><time datetime="${item.date}">${item.date}</time></div><h4><span>${item.version}</span> ${content.name}</h4><p>${content.intro}</p><div class="rose-v2-history-changes">${content.changes.map(([title,body],i)=>`<section><b>0${i+1}</b><div><h5>${title}</h5><p>${body}</p></div></section>`).join('')}</div><p class="rose-v2-history-note">${content.note}</p><a href="${roseraieReleaseUrl(item.version)}" target="_blank" rel="noopener noreferrer">${t('查看 GitHub 发布页','View the GitHub release')} <span aria-hidden="true">↗</span></a></article>`}).join('')}</div></details>`;
}

export function roseraieCard(){
  return `<article class="exhibit exhibit--roseraie rose-v2" id="project-roseraie"><div class="rose-ribbon"><span>CHEFZC / THE DIGITAL COLLECTION</span><span>NO. 08 <b>✧</b> ROSERAIE · 0.2.0</span></div><div class="rose-hero rose-v2-hero">${petals(20)}<div class="rose-v2-atmosphere" aria-hidden="true"></div><div class="rose-hero-copy"><span class="rose-overline">LE SALON DES POSSIBLES</span><img class="rose-v2-hero-mark" src="${mark}" width="92" height="92" alt=""><h3>Roseraie<span>.</span></h3><p class="rose-hero-cn">蔷薇工坊</p><h4>${t('让灵感，<br>在此盛放。','A little grace<br>in every great idea.')}</h4><p>${t('在紫罗兰色的沙龙里，把一个念头交给真正会工作的 Agent。模型、推理、执行与审阅，留在同一处清楚可见。','In a violet salon, give an idea to an agent that can actually work. Model choice, reasoning, action and review stay in one legible place.')}</p><button type="button" data-project="roseraie">${t('走进紫罗兰工坊','Enter the violet atelier')} <span>↗</span></button></div><div class="rose-hero-art rose-v2-hero-art"><span class="rose-v2-ring rose-v2-ring--outer" aria-hidden="true"></span><span class="rose-v2-ring rose-v2-ring--inner" aria-hidden="true"></span><div class="rose-v2-botanical-halo" aria-hidden="true"></div><img class="rose-v2-botanical" src="${botanical}" width="768" height="768" alt="" loading="lazy"><div class="rose-preview-window rose-v2-preview"><span>ROSERAIE / 0.2.0 <b>− □ ×</b></span><img src="${home}" width="2304" height="1517" alt="${t('Roseraie 0.2.0 的真实 Windows 首页','Actual Roseraie 0.2.0 Windows home')}" loading="lazy"><small>${t('真实桌面界面 / WINDOWS x64','ACTUAL DESKTOP INTERFACE / WINDOWS x64')}</small></div><div class="rose-v2-medallion" aria-hidden="true">R <small>ATELIER</small></div></div><div class="rose-hero-foot"><span>THE ROCOCO AGENT ATELIER</span><span>WINDOWS · LOCAL · 中 / EN</span></div></div><div class="rose-prologue rose-v2-prologue"><div><span>AN AGENT WITH A PLACE TO THINK</span><h3>${t('每一步，都有形状。<br><em>每个决定，都看得见。</em>','A place for each step.<br><em>A reason for each choice.</em>')}</h3></div><p>${t('在所选工作空间里阅读、写入、运行命令；需要影响文件或终端时，先交给你确认。0.2 让任务模型和推理强度直接出现在沙龙，也让织思的审阅阶段拥有自己的选择。','Read, write and run commands in a chosen workspace, with your approval before file or terminal impact. Version 0.2 puts model and effort choice in the salon and gives Weave review its own selection.')}</p></div><div class="rose-triptych rose-v2-triptych"><div><span>THE ROOM</span><b>✧</b><strong>${t('紫罗兰瓷釉','VIOLET PORCELAIN')}</strong><p>${t('植物画、银丝与柔光','Botanical art, filigree and light')}</p></div><div><span>THE MODEL</span><b>✦</b><strong>${t('自由选择','CHOOSE WITH INTENT')}</strong><p>GPT-6 Sol / Astra / Luna</p></div><div><span>THE WEAVE</span><b>❦</b><strong>${t('分层思考','A SECOND VIEW')}</strong><p>${t('执行、只读质询、定稿','Execute, challenge, refine')}</p></div></div>${roseraieGallery()}${roseraieHistory()}<div class="rose-closing rose-v2-closing"><div><span>THE NEXT IDEA IS YOURS.</span><strong>${t('给下一个想法，<br>留一朵玫瑰。','LET THE NEXT IDEA<br>TAKE ROOT.')}</strong></div>${actions()}</div><footer class="rose-footer"><span>ROSERAIE / 蔷薇工坊</span><span>CHEFZC · 2026 <b>✧</b> VERSION 0.2.0</span></footer></article>`;
}
export function roseraieDetail(view='salon'){
  return `<div class="rose-detail rose-v2-detail"><div class="rose-detail-head"><img src="${mark}" width="82" height="82" alt=""><span>ATELIER Nº 08 / WINDOWS x64 / 0.2.0</span><h2 id="dialog-title">Roseraie<span>.</span></h2><p>${t('让灵感，在此盛放。','A little grace in every great idea.')}</p></div>${roseraieGallery(view)}<div class="rose-detail-grid"><section><small>I / THE WORKBENCH</small><h3>${t('能做事，也知道何时停下来。','An agent that knows when to pause.')}</h3><p>${t('在本地工作空间对话、读取文件、调用工具，批准后才写入或运行命令。检查点、手账与上下文胶囊让过程可追溯。','Chat in a local workspace, read files and call tools. Writes and commands wait for approval. Checkpoints, a journal and context capsules make the process traceable.')}</p></section><section><small>II / THE VIOLET EDITION</small><h3>${t('把模型选择，放回创作现场。','Model choice belongs in the room.')}</h3><p>${t('0.2.0 为任务和织思审阅增加模型与推理强度选择，并升级了紫罗兰植物画界面。本机 Codex CLI 的 Sol、Astra、Luna 已测试；其他服务取决于账户。Windows 包未签名。','Version 0.2.0 adds model and effort choice for tasks and Weave review, with a violet botanical redesign. Sol, Astra and Luna were tested via the local Codex CLI; other services depend on account access. Windows packages are unsigned.')}</p></section></div>${roseraieHistory('roseraie-detail-history')}${actions()}</div>`;
}
export function roseraieNowArt(edition='0.2'){
  const latest=edition==='0.2';
  return `<div class="milestone-art rose-now-art rose-v2-now ${latest?'rose-v2-now--latest':'rose-v2-now--first'}" data-roseraie-now="${edition}" aria-hidden="true">${petals(latest?10:7)}<div class="rose-now-head"><span>ROSERAIE / ${latest?'THE VIOLET EDITION':'THE FIRST ROSE'}</span><b>✧</b></div><div class="rose-v2-now-orbit" aria-hidden="true"></div><img class="rose-v2-now-flower" src="${botanical}" width="768" height="768" alt=""><div class="rose-v2-now-title"><span>${latest?'A NEW ROOM FOR IDEAS':'WHERE IT BEGAN'}</span><strong>Roseraie<i>.</i></strong><small>${latest?t('让每种想法，找到自己的模型。','A model for each idea.'):t('让灵感，在此盛放。','A little grace in every idea.')}</small></div><div class="rose-v2-now-bottom"><span>${latest?'MODEL · EFFORT · WEAVE':'FRAME · QUESTION · CRAFT'}</span><b>${latest?'0.2.0':'0.1.0'}</b></div></div>`;
}
